"""
Tests of the world model, the grounding and the orchestrator's use of them (src/world_model.py, src/grounding.py, src/orchestrator.py) with fakes, no simulator.

    python experiments/grounding_test.py

1. World model: upsert, get, entries by kind, what a hand holds, a source refreshed by object_pose, unknown ids and stances raise, perception-style replacement of the source; navigation targets as phrases (an object or fixture on the bench gives the bench's stance; unknown, stanceless and ambiguous targets raise).
2. Phrase matching: articles, names, phrases, property words (full, empty, hot), modifiers that the entry does not have, no noun ("the full one"), unknown objects.
3. Grounding: one match; not found calls the search and, with the stub, stops with "search not implemented"; a search that finds an entry grounds it; several matches with no operator stop with
   "ambiguous reference" and the candidates; with an operator the candidates are shown, the choice is logged, a bad answer stops; a place step prefers the candidate in the hand; the
   step checks (pick: not held, hand empty; place: the object is the one in the hand, a destination).
4. Orchestrator with fake modules: a tagged plan runs, the grounded ids reach the manipulation module; a step with primitive "other" stops with "no primitive for this step" after the earlier
   steps ran; a grounding failure stops with its reason; the operator question shows in the phase text and the plan waits (no commands) until the answer; an untagged plan or a missing
   grounder is refused at construction.
"""

import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))

import numpy as np  # noqa: E402

from src.grounding import make_grounder, make_operator, make_scripted_operator, make_search_stub, resolve  # noqa: E402
from src.mpvi_postprocess import make_stored_labeler, postprocess  # noqa: E402
from src.orchestrator import make_orchestrator  # noqa: E402
from src.world_model import Entry, WorldModel  # noqa: E402

results = []


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}")


def obj(id_, phrases, x, contents="empty", held_by=None, kind="object", **props):
    return Entry(id_, id_, tuple(phrases), kind, np.array([x, 0.0, 0.8]), np.array([0.0, 0.0, 1.0]), {"contents": contents, "held_by": held_by, "height": 0.1, **props}, "sim_ground_truth", 0.0)


def fixture(id_, phrases, x):
    return Entry(id_, id_, tuple(phrases), "fixture", np.array([x, 0.0, 0.8]), None, {}, "map", 0.0)


def make_world(*entries):
    w = WorldModel()
    for e in entries:
        w.upsert(e)
    return w


def ids(entries):
    return [e.id for e in entries]


def man(step_text, prim, *objs):
    return {"description": step_text, "primitive": prim, "objects": [{"phrase": p, "role": r} for p, r in objs], "index": 1, "check": True}


def main():
    print("1. world model")
    calls = []

    def source(world, t):
        calls.append(t)
        world.upsert(obj("beaker", ["beaker"], 0.1 * len(calls)))
    w = WorldModel([source])
    w.refresh(2.0)
    check("a refresh runs the source with the time and fills the model", calls == [2.0] and ids(w.entries()) == ["beaker"] and w.time == 2.0)
    p = w.object_pose("beaker")
    check("object_pose refreshes first and gives copies", len(calls) == 2 and np.isclose(p["position"][0], 0.2) and p["position"] is not w.get("beaker").position)
    w.upsert(fixture("hotplate", ["hotplate"], 1.0))
    w.upsert(obj("flask", ["flask"], 0.5, held_by="left"))
    check("entries by kind, and what a hand holds", ids(w.entries("fixture")) == ["hotplate"] and ids(w.entries("object")) == ["beaker", "flask"] and ids(w.held_by("left")) == ["flask"] and w.held_by("right") == [])
    for name, fn in (("an unknown id", lambda: w.get("lid")), ("a stance for an entry without one", lambda: w.stance("hotplate")), ("a stance for an unknown target", lambda: w.stance("nowhere"))):
        try:
            fn()
            ok = False
        except KeyError:
            ok = True
        check(f"{name} raises KeyError", ok)
    st = {"xy": (0.7, 1.0), "yaw": -1.5, "pedestal_q": 0.1}
    nav = make_world(Entry("bench", "bench", ("bench", "lab bench"), "fixture", np.zeros(3), None, {"stance": st}), obj("beaker", ["beaker"], 0.1, location="bench"),
                     Entry("hotplate", "hotplate", ("hotplate", "hot plate"), "fixture", np.zeros(3), None, {"location": "bench"}), obj("lamp", ["lamp"], 0.2))
    check("navigation targets: an id, a phrase, an object or a fixture standing on the bench all give the bench's stance",
          all(nav.stance(t) == st for t in ("bench", "the lab bench", "the beaker", "hotplate", "the hot plate")))
    for name, t, text in (("an unknown phrase", "kitchen", "no navigation target"), ("an object with no location or stance", "the lamp", "has no stance")):
        try:
            nav.stance(t)
            ok = False
        except KeyError as e:
            ok = text in e.args[0]
        check(f"navigation target: {name} raises KeyError", ok)
    nav.upsert(Entry("shelf", "shelf", ("shelf",), "fixture", np.zeros(3), None, {"stance": {"xy": (2.0, 2.0), "yaw": 0.0, "pedestal_q": 0.1}}))
    nav.upsert(obj("beaker2", ["beaker"], 0.5, location="shelf"))
    try:
        nav.stance("the beaker")
        ok = False
    except KeyError as e:
        ok = "ambiguous" in e.args[0]
    check("navigation target: a phrase whose matches stand at different stances is ambiguous", ok)
    w.remove("flask")
    w.sources[0] = lambda world, t: world.upsert(obj("beaker", ["beaker"], 9.0, found="detector") if False else Entry("beaker", "beaker", ("beaker",), "object", np.array([9.0, 0, 0.8]), None, {}, "detector", t))
    w.refresh(3.0)
    check("a perception-style source replaces the ground truth with found = detector, nothing else changes", w.get("beaker").found == "detector" and w.get("beaker").last_seen == 3.0 and "flask" not in ids(w.entries()))

    print("\n2. phrase matching")
    w = make_world(obj("beaker_full", ["beaker", "glass beaker"], 0.1, contents="liquid"), obj("beaker_empty", ["beaker"], 0.2), fixture("hotplate", ["hotplate", "hot plate"], 1.0),
                   obj("tube", ["test tube", "tube"], 0.3), obj("plate", ["plate"], 0.4, hot=True))
    for phrase, want in [("the hotplate", ["hotplate"]), ("The Hot Plate.", ["hotplate"]), ("a beaker", ["beaker_full", "beaker_empty"]), ("the full beaker", ["beaker_full"]), ("the empty beaker", ["beaker_empty"]),
                         ("the glass beaker", ["beaker_full"]), ("the red beaker", []), ("the test tube", ["tube"]), ("the tube", ["tube"]), ("the hot plate", ["hotplate"]), ("the hot one", ["plate"]),
                         ("the full one", ["beaker_full"]), ("the empty one", ["beaker_empty", "hotplate", "tube", "plate"]), ("the flask", []), ("", ["beaker_full", "beaker_empty", "hotplate", "tube", "plate"])]:
        got = ids(resolve(w, phrase))
        check(f"{phrase!r} -> {want}", got == want, f"got {got}")

    print("\n3. grounding")
    one = make_world(obj("beaker", ["beaker"], 0.1), fixture("hotplate", ["hotplate"], 1.0))
    g = make_grounder(one)
    r = g["begin"](man("Pick up the beaker", "pick", ("the beaker", "manipulated")))
    check("one match: resolved", r["state"] == "resolved" and r["resolved"]["manipulated"].id == "beaker")
    r = g["begin"](man("Pick up the flask", "pick", ("the flask", "manipulated")))
    check("not found: the stub search stops the plan with 'search not implemented'", r["state"] == "failed" and r["reason"] == "object not found, search not implemented: the flask" and any(e["kind"] == "search" for e in g["log"]))
    found = Entry("flask", "flask", ("flask",), "object", np.array([0.5, 0, 0.8]), None, {"contents": "empty", "held_by": None}, "detector", 1.0)
    g2 = make_grounder(one, {"name": "fake search", "search": lambda phrase, world: {"status": "found", "entries": [found]}})
    r = g2["begin"](man("Pick up the flask", "pick", ("the flask", "manipulated")))
    check("a search that finds the object: written into the world model and grounded", r["state"] == "resolved" and r["resolved"]["manipulated"].id == "flask" and "flask" in ids(one.entries()))
    g3 = make_grounder(one, {"name": "fake search", "search": lambda phrase, world: {"status": "not_found", "entries": []}})
    r = g3["begin"](man("Pick up the lid", "pick", ("the lid", "manipulated")))
    check("a search that finds nothing stops with 'object not found'", r["state"] == "failed" and r["reason"] == "object not found: the lid")
    two = make_world(obj("b1", ["beaker"], 0.1, contents="liquid"), obj("b2", ["beaker"], 0.2), fixture("hotplate", ["hotplate"], 1.0))
    step = man("Pick up the beaker", "pick", ("the beaker", "manipulated"))
    r = make_grounder(two)["begin"](step)
    check("several matches, no operator: 'ambiguous reference' with the candidates (positions and properties)", r["state"] == "failed" and r["reason"].startswith("ambiguous reference: 'the beaker'") and "b1 (object) at (0.10" in r["reason"] and "contents liquid" in r["reason"] and "b2" in r["reason"], r.get("reason"))
    op = make_scripted_operator([2], polls=2)
    g = make_grounder(two, operator=op)
    r = g["begin"](step)
    check("with an operator: the question is asked with the candidates and the state is 'asking'", r["state"] == "asking" and ids(r["candidates"]) == ["b1", "b2"] and op["asked"] == [("the beaker", ["b1", "b2"])])
    check("the viewer text lists the candidates", "ASK OPERATOR 'the beaker'" in g["phase"]() and "1) b1" in g["phase"]() and "2) b2" in g["phase"]())
    states = [g["poll"]()["state"] for _ in range(3)]
    r = g["poll"]() if states[-1] == "asking" else None
    check("the plan waits until the operator answers, then resolves to the chosen one", states[:2] == ["asking", "asking"] and states[2] == "resolved", f"{states}")
    chose = [e for e in g["log"] if e["kind"] == "operator_chose"]
    check("the choice is logged with the phrase, the number and the entry", len(chose) == 1 and chose[0]["chosen"] == "b2" and chose[0]["number"] == 2 and chose[0]["phrase"] == "the beaker")
    g = make_grounder(two, operator=make_scripted_operator([5], polls=0))
    g["begin"](step)
    r = g["poll"]()
    check("an answer outside the candidates stops the plan", r["state"] == "failed" and "not one of 1 to 2" in r["reason"])
    held = make_world(obj("b1", ["beaker"], 0.1), obj("b2", ["beaker"], 0.2, held_by="left"), fixture("hotplate", ["hotplate"], 1.0))
    place = man("Place the beaker on the hotplate", "place", ("the beaker", "manipulated"), ("the hotplate", "destination"))
    r = make_grounder(held)["begin"](place)
    check("a place step with two beakers: the one in the hand is chosen without asking", r["state"] == "resolved" and r["resolved"]["manipulated"].id == "b2" and r["resolved"]["destination"].id == "hotplate")
    r = make_grounder(one)["begin"](place)
    check("a place step whose object is not in the hand stops, saying what the hand holds", r["state"] == "failed" and "not the one in the left hand" in r["reason"] and "holds nothing" in r["reason"], r.get("reason"))
    solo = make_world(obj("b2", ["beaker"], 0.2, held_by="left"), fixture("hotplate", ["hotplate"], 1.0))
    r = make_grounder(solo, side="right")["begin"](place)
    check("the place step checks the manipulating hand (the left hand holds the beaker, the right hand is the one placing)", r["state"] == "failed" and "not the one in the right hand" in r["reason"] and "holds nothing" in r["reason"], r.get("reason"))
    other = make_world(obj("b1", ["beaker"], 0.1), obj("flask", ["flask"], 0.5, held_by="left"), fixture("hotplate", ["hotplate"], 1.0))
    r = make_grounder(other)["begin"](place)
    check("a place step whose beaker is not the one held: the reason names what the hand holds", r["state"] == "failed" and "holds flask" in r["reason"], r.get("reason"))
    r = make_grounder(one)["begin"](man("Place it", "place", ("the beaker", "manipulated")))
    check("a place step without a destination stops", r["state"] == "failed" and "destination" in r["reason"])
    r = make_grounder(solo)["begin"](man("Pick up the beaker", "pick", ("the beaker", "manipulated")))
    check("a pick of an object that is already held stops", r["state"] == "failed" and "already held by the left hand" in r["reason"], r.get("reason"))
    r = make_grounder(make_world(obj("b1", ["beaker"], 0.1), obj("flask", ["flask"], 0.5, held_by="left")))["begin"](step)
    check("a pick with a hand that holds something else stops", r["state"] == "failed" and "not empty" in r["reason"] and "flask" in r["reason"])
    r = make_grounder(one)["begin"](man("Pick up", "pick"))
    check("a pick that names no object stops", r["state"] == "failed")

    print("\n4. the orchestrator with fake modules")

    class Mod:
        """A fake navigation or manipulation module that is done after `ticks` steps."""

        def __init__(self, ticks=2, on_start=None):
            self.ticks, self.n, self.started, self.err, self.on_start = ticks, 0, [], None, on_start

        def module(self):
            return {"name": "fake", "start": self.start, "step": self.step, "done": lambda: self.n >= self.ticks, "error": lambda: self.err, "phase": lambda: "PH", "events": lambda: [],
                    "resume": lambda: None, "report": lambda: {}}

        def start(self, seg):
            self.started.append(seg)
            self.n = 0
            if self.on_start:
                self.on_start(seg)

        def step(self, obs):
            self.n += 1
            return {"cmd": 1}

    def build(world, plan_steps, operator=None, search=None, on_start=None):
        nav, mp = Mod(), Mod(on_start=on_start)
        plan = {"task_name": "t", "segments": plan_steps}
        mods = {"navigation": nav.module(), "manipulation": mp.module(), "checker": {"check": lambda seg, ev, obs: {"passed": True, "reason": "", "details": {}}}, "world": world,
                "grounder": make_grounder(world, search, operator)}
        return make_orchestrator(plan, mods), nav, mp

    def run(orch, n=40):
        outs = []
        for k in range(n):
            outs.append(orch["step"]({"time": 0.01 * k}))
            if orch["state"]["finished"] or orch["state"]["failure"]:
                break
        return outs

    def plan_of(*manips, nav_first=True, labels):
        segs = ([{"type": "navigation", "description": "Go to the bench", "completion_criteria": "there", "target": "bench"}] if nav_first else []) + [
            {"type": "manipulation", "description": d, "completion_criteria": "done", "target": None} for d in manips]
        return postprocess({"task_name": "t", "segments": segs}, make_stored_labeler({"labels": labels}), say=lambda *_: None)

    lab = lambda i, prim, *objs: {"index": i, "primitive": prim, "objects": [{"phrase": p, "role": r} for p, r in objs]}  # noqa: E731
    bm = ("the beaker", "manipulated")
    hd = ("the hotplate", "destination")
    tagged = plan_of("Pick up the beaker", "Place the beaker on the hotplate", labels=[lab(1, "pick", bm), lab(2, "place", bm, hd)])
    w = make_world(obj("beaker", ["beaker"], 0.1, held_by=None), fixture("hotplate", ["hotplate"], 1.0))
    # the fake manipulation module "picks" the beaker: after the pick segment starts the beaker is in the hand
    orch, nav, mp = build(w, tagged["segments"], on_start=lambda seg: w.get("beaker").properties.update(held_by="left") if seg["primitive"] == "pick" else None)
    outs = run(orch)
    s = orch["state"]
    check("the tagged plan runs to the end", s["finished"] and not s["failure"] and all(x == "done" for x in s["status"]), f"{s['status']} {s['failure']}")
    check("the grounded ids reach the manipulation module with the segment", [x["grounded"] for x in mp.started] == [{"manipulated": "beaker"}, {"manipulated": "beaker", "destination": "hotplate"}], f"{[x.get('grounded') for x in mp.started]}")
    check("the navigation segment is started without grounding", "grounded" not in nav.started[0])
    check("the report carries the grounding log and the grounded ids", len(orch["report"]()["grounded"]) == 2 and any(e["kind"] == "resolved" for e in orch["report"]()["grounding_log"]))
    tagged = plan_of("Pick up the beaker", "Juggle the beaker", labels=[lab(1, "pick", bm), lab(2, "other", bm)])
    w = make_world(obj("beaker", ["beaker"], 0.1), fixture("hotplate", ["hotplate"], 1.0))
    orch, nav, mp = build(w, tagged["segments"])
    run(orch)
    s = orch["state"]
    check("a step with primitive 'other' stops with 'no primitive for this step', after the earlier steps ran", s["failure"] and "no primitive for this step: Juggle the beaker" in s["failure"] and s["status"][1] == "done" and len(mp.started) == 1, f"{s['failure']}")
    check("the policy status carries PLAN_FAILED", orch["status"]()["failure_outcome"] == "PLAN_FAILED")
    tagged = plan_of("Pick up the beaker", labels=[lab(1, "pick", bm)])
    orch, nav, mp = build(make_world(fixture("hotplate", ["hotplate"], 1.0)), tagged["segments"])
    run(orch)
    check("an unknown object stops the plan with the search stub's reason, and the manipulation module is never started", "search not implemented: the beaker" in orch["state"]["failure"] and mp.started == [])
    w = make_world(obj("b1", ["beaker"], 0.1, contents="liquid"), obj("b2", ["beaker"], 0.2), fixture("hotplate", ["hotplate"], 1.0))
    orch, nav, mp = build(w, tagged["segments"])
    run(orch)
    check("an ambiguous reference with no operator stops the plan", "ambiguous reference: 'the beaker'" in orch["state"]["failure"] and mp.started == [])
    op = make_scripted_operator([2], polls=3)
    orch, nav, mp = build(w, tagged["segments"], operator=op)
    outs = run(orch, 12)
    phases = []
    orch, nav, mp = build(w, tagged["segments"], operator=make_scripted_operator([2], polls=3))
    for k in range(40):
        c = orch["step"]({"time": 0.01 * k})
        phases.append((orch["status"]()["phase"], c))
        if orch["state"]["finished"] or orch["state"]["failure"]:
            break
    asking = [p for p, c in phases if "ASK OPERATOR" in p]
    check("the operator question shows in the phase text and the plan sends no commands while it waits", len(asking) >= 3 and all(c is None for p, c in phases if "ASK OPERATOR" in p) and "[grounding]" in asking[0], f"{len(asking)} ticks; {asking[0] if asking else ''}"[:200])
    check("after the answer the chosen object goes to the module and the plan finishes", orch["state"]["finished"] and mp.started[0]["grounded"] == {"manipulated": "b2"}, f"{orch['state']['failure']}")
    for name, fn in (("an untagged plan", lambda: make_orchestrator({"task_name": "t", "segments": [{"type": "manipulation", "description": "Pick up", "completion_criteria": "c", "target": None}]},
                                                                      {"grounder": None})),
                     ("a plan with manipulation and no grounder", lambda: make_orchestrator(tagged, {}))):
        try:
            fn()
            ok = False
        except ValueError:
            ok = True
        check(f"{name} is refused at construction", ok)
    print(f"\n{sum(results)}/{len(results)} checks passed")
    return all(results)


if __name__ == "__main__":
    sys.exit(0 if main() else 1)
